def digitSum(s):
    total = 0
    for char in s:
        if char.isupper():
            total += ord(char)
    return total

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if char.islower():
                pos = ord(char) - ord('a')
                if pos % 2 == 1:
                    count += 1
        return count

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()

from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ""
    balance = 0

    for char in paren_string.replace(' ', ''):
        if char == '(':
            if balance == 0:
                current_group = ""
            balance += 1
            current_group += char
        elif char == ')':
            balance -= 1
            current_group += char
            if balance == 0:
                result.append(current_group)
                current_group = ""

    return result

def file_name_check(file_name):
    if file_name.count('.') != 1:
        return 'No'

    dot_index = file_name.find('.')
    prefix = file_name[:dot_index]
    suffix = file_name[dot_index+1:]

    if not prefix or not prefix[0].isalpha():
        return 'No'

    if suffix not in ['txt', 'exe', 'dll']:
        return 'No'

    digit_count = sum(1 for c in file_name if c.isdigit())
    if digit_count > 3:
        return 'No'

    return 'Yes'

from typing import List, Tuple
from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []
    result = [numbers[0]]
    current_max = numbers[0]
    for num in numbers[1:]:
        if num > current_max:
            current_max = num
        result.append(current_max)
    return result

def any_int(x, y, z):
    # Check if all numbers are integers
    if not all(isinstance(n, int) for n in [x, y, z]):
        return False

    # Check if one number is the sum of the other two
    return x == y + z or y == x + z or z == x + y

def next_smallest(lst):
    if len(lst) < 2:
        return None
    unique_vals = list(set(lst))
    if len(unique_vals) < 2:
        return None
    unique_vals.sort()
    return unique_vals[1]

def solve(N):
    if N == 0:
        return "0"
    digit_sum = sum(int(d) for d in str(N))
    return bin(digit_sum)[2:]

def f(n):
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            factorial = 1
            for j in range(1, i + 1):
                factorial *= j
            result.append(factorial)
        else:
            # Sum of numbers from 1 to i
            summation = i * (i + 1) // 2
            result.append(summation)
    return result
